{
  "apiVersion": "gateway.api-platform.wso2.com/v1",
  "kind": "RestApi",
  "metadata": {
    "name": "oai-pm-backend-sim"
  },
  "spec": {
    "displayName": "OpenAI errors Postman backend simulator",
    "version": "v1.0",
    "context": "/oai-pm-backend-sim/$version",
    "upstream": {
      "main": {
        "url": "{{restSampleUpstream}}"
      }
    },
    "operations": [
      {
        "method": "POST",
        "path": "/chat/completions",
        "policies": [
          {
            "name": "respond",
            "version": "v1",
            "params": {
              "statusCode": 200,
              "body": "{\"id\":\"chatcmpl-1\",\"object\":\"chat.completion\",\"choices\":[{\"index\":0,\"message\":{\"role\":\"assistant\",\"content\":\"hello\"},\"finish_reason\":\"stop\"}],\"usage\":{\"prompt_tokens\":3,\"completion_tokens\":1,\"total_tokens\":4}}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "method": "GET",
        "path": "/teapot",
        "policies": [
          {
            "name": "respond",
            "version": "v1",
            "params": {
              "statusCode": 418,
              "body": "{\"vendor_error\":\"I am a teapot\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "method": "GET",
        "path": "/openai-shaped",
        "policies": [
          {
            "name": "respond",
            "version": "v1",
            "params": {
              "statusCode": 429,
              "body": "{\"error\":{\"message\":\"Rate limit reached for gpt-4o in organization org-x\",\"type\":\"requests\",\"param\":null,\"code\":\"rate_limit_exceeded\"}}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "method": "GET",
        "path": "/anthropic-shaped",
        "policies": [
          {
            "name": "respond",
            "version": "v1",
            "params": {
              "statusCode": 529,
              "body": "{\"type\":\"error\",\"error\":{\"type\":\"overloaded_error\",\"message\":\"Overloaded\"}}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "method": "GET",
        "path": "/empty-429",
        "policies": [
          {
            "name": "respond",
            "version": "v1",
            "params": {
              "statusCode": 429,
              "body": "",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "method": "GET",
        "path": "/empty-500",
        "policies": [
          {
            "name": "respond",
            "version": "v1",
            "params": {
              "statusCode": 500,
              "body": "",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      }
    ]
  }
}

{
  "apiVersion": "gateway.api-platform.wso2.com/v1",
  "kind": "LlmProvider",
  "metadata": {
    "name": "oai-pm-openai"
  },
  "spec": {
    "displayName": "OpenAI errors Postman openai",
    "version": "v1.0",
    "template": "openai",
    "context": "/oai-pm-openai",
    "upstream": {
      "url": "{{selfUpstream}}/oai-pm-backend-sim/v1.0"
    },
    "accessControl": {
      "mode": "allow_all"
    },
    "policies": [
      {
        "name": "word-count-guardrail",
        "version": "v1",
        "paths": [
          {
            "path": "/chat/completions",
            "methods": [
              "POST"
            ],
            "params": {
              "request": {
                "min": 1,
                "max": 5,
                "jsonPath": "$.prompt"
              }
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/message",
            "methods": [
              "GET",
              "HEAD"
            ],
            "params": {
              "statusCode": 403,
              "body": "{\"error\":\"Forbidden\",\"message\":\"Caller is not allowed to use this model\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/error-description",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 401,
              "body": "{\"error\":\"invalid_token\",\"error_description\":\"Token expired\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/detail",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 404,
              "body": "{\"detail\":\"Model gpt-9 does not exist\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/error-string",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 400,
              "body": "{\"error\":\"Malformed request\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/object-message",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 422,
              "body": "{\"type\":\"WORD_COUNT_GUARDRAIL\",\"message\":{\"action\":\"GUARDRAIL_INTERVENED\",\"actionReason\":\"too long\"}}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/plain-text",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 429,
              "body": "Slow down, too many requests",
              "headers": [
                {
                  "name": "content-type",
                  "value": "text/plain"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/html",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 502,
              "body": "<html><body><h1>Bad Gateway</h1></body></html>",
              "headers": [
                {
                  "name": "content-type",
                  "value": "text/html"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/empty",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 503,
              "body": "",
              "headers": [
                {
                  "name": "content-type",
                  "value": "text/plain"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/unusual-status",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 451,
              "body": "{\"message\":\"Unavailable for legal reasons\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/nested-error-message",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 409,
              "body": "{\"error\":{\"message\":\"Conflict on resource\",\"reason\":\"x\"}}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/already-openai",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 400,
              "body": "{\"error\":{\"message\":\"The model gpt-9 does not exist\",\"type\":\"invalid_request_error\",\"param\":\"model\",\"code\":\"model_not_found\"}}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/success",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 200,
              "body": "{\"ok\":true}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      }
    ]
  }
}

